export function enablePrototypeWindow(onResize){const layout=document.querySelector('#review-layout'),panel=layout.querySelector('.prototype-column');let ratio=Number(localStorage.getItem('prd-split-ratio'))||.64;const divider=document.createElement('div');divider.className='prd-split-divider';divider.tabIndex=0;divider.setAttribute('role','separator');divider.setAttribute('aria-label','调整原型和PRD宽度');divider.setAttribute('aria-orientation','vertical');panel.after(divider);function apply(next){const width=layout.clientWidth;if(width<650)return;ratio=Math.max(300/width,Math.min(1-300/width,next));layout.style.gridTemplateColumns=`minmax(0,${ratio}fr) 10px minmax(0,${1-ratio}fr)`;divider.setAttribute('aria-valuenow',String(Math.round(ratio*100)));divider.setAttribute('aria-valuemin','20');divider.setAttribute('aria-valuemax','80');localStorage.setItem('prd-split-ratio',String(ratio));requestAnimationFrame(()=>onResize?.())}divider.onpointerdown=e=>{divider.setPointerCapture(e.pointerId);layout.classList.add('resizing');divider.onpointermove=event=>{const r=layout.getBoundingClientRect();apply((event.clientX-r.left)/r.width)};const finish=()=>{divider.onpointermove=null;layout.classList.remove('resizing')};divider.onpointerup=finish;divider.onpointercancel=finish};divider.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','Home'].includes(e.key))return;e.preventDefault();apply(e.key==='Home'?.64:ratio+(e.key==='ArrowRight'?.03:-.03))};divider.ondblclick=()=>apply(.64);new ResizeObserver(()=>apply(ratio)).observe(layout);apply(ratio)}
